cypress_script:
describe('Login Form', () => {
  it('should log in successfully with valid credentials', () => {
    cy.visit('https://practicesoftwaretesting.com/auth/login');
    cy.get('#email').type('user@example.com');
    cy.get('#password').type('password123');
    cy.get('[data-test="login-submit"]').click();
    cy.url().should('not.include', '/auth/login');
  });
  it('should not log in with empty credentials', () => {
    cy.visit('https://practicesoftwaretesting.com/auth/login');
    cy.get('[data-test="login-submit"]').click();
    cy.url().should('include', '/auth/login');
    cy.get('[data-test="nav-sign-in"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Form', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/auth/login');
    await page.fill('#email', 'user@example.com');
    await page.fill('#password', 'password123');
    await page.click('[data-test="login-submit"]');
    await expect(page).toHaveURL(/^(?!.*auth\/login).*/);
  });
  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/auth/login');
    await page.click('[data-test="login-submit"]');
    await expect(page).toHaveURL('https://practicesoftwaretesting.com/auth/login');
    await expect(page.locator('[data-test="nav-sign-in"]')).toBeVisible();
  });
});
